def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None:
        v = s.get('basic_structure_statistics', {}).get('volume_per_atom_A3')
    if v is None or not math.isfinite(v) or v <= 0:
        return 0.0
    return float(math.log1p(v))

def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None or v <= 0 or not math.isfinite(v):
        return 0.0
    props = s.get('element_properties', {})
    total = 0.0
    weight = 0.0
    for e, x in s.get('composition', {}).items():
        r = props.get(e, {}).get('covalent_radius_A')
        if x is not None and x > 0 and r is not None and r > 0 and math.isfinite(r):
            total += x * r * r * r
            weight += x
    if weight <= 0:
        return 0.0
    return float(4.0 * math.pi * total / (3.0 * weight * v))

def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None or v <= 0 or not math.isfinite(v):
        return 0.0
    props = s.get('element_properties', {})
    total = 0.0
    weight = 0.0
    for e, x in s.get('composition', {}).items():
        z = props.get(e, {}).get('valence_electrons')
        if x is not None and x > 0 and z is not None and math.isfinite(z):
            total += x * z
            weight += x
    return float(total / (weight * v)) if weight > 0 else 0.0

def feature(s):
    sites = s.get('sites', ())
    n = len(sites)
    occ = [max(0.0, float(t.get('occupancy', 1.0) or 0.0)) for t in sites]
    total_occ = sum(occ)
    if total_occ <= 0:
        return 0.0
    volume = s.get('lattice', {}).get('volume_A3')
    if volume is None:
        v = s.get('volume_per_atom_A3')
        volume = v * total_occ if v is not None else 0.0
    if volume <= 0 or not math.isfinite(volume):
        return 0.0
    contacts = 0.0
    for b in s.get('neighbors', ()):
        i = b['i']
        j = b['j']
        d = b.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and 0 < d <= 6.0:
            contacts += occ[i] * occ[j]
    sphere = 4.0 * math.pi * 6.0 ** 3 / 3.0
    return float(contacts * volume / (total_occ * total_occ * sphere))
